def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 28.0))

    prev_bids = []
    bob_like = []
    cindy_like = []
    urgent_opp = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 110:
                cindy_like.append(float(bid))
            elif bid > 0:
                bob_like.append(float(bid))
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1

    slots = max(1, int(supply // WATER_REQ))
    tight = slots <= 1

    bob_anchor = 72.0
    if bob_like:
        bob_anchor = max(bob_like)

    cindy_anchor = 125.0
    if cindy_like:
        cindy_anchor = max(cindy_like)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(90.0, bob_anchor + 8.0))
        if tight and urgent_opp > 0:
            bid = min(budget, bid + 8.0)
        return float(max(0.0, bid))

    if hp <= 4 or no_water_days >= 1:
        if tight:
            bid = min(budget, max(82.0, bob_anchor + 3.0))
        else:
            bid = min(budget, max(68.0, bob_anchor - 2.0))
        return float(max(0.0, bid))

    if tight:
        if cindy_like:
            bid = min(budget, max(34.0, bob_anchor + 1.5))
        else:
            bid = min(budget, max(60.0, bob_anchor + 2.0))
    else:
        bid = 26.0
        if len(alive) >= 2:
            bid = 32.0
        if urgent_opp > 0:
            bid += 4.0
        if day >= 8:
            bid += 6.0
        bid = min(budget, bid)

    if budget < 120:
        bid = min(bid, budget * 0.42)
    elif budget > 500 and hp >= 7 and not tight:
        bid = max(bid, 30.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    competitive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if opp_id == "Bob" or opp_id == "Alex" or (prev_trace and prev_trace.get('bid', 0) > 0.01):
                competitive_opponents.append(opp)

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.4

    if day_context['supply'] < WATER_REQ * 1.5:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)
    elif day_context['supply'] < WATER_REQ * 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.65)
    else:
        base_bid = min(base_bid, DAILY_SALARY * 0.5)

    yesterday_competitive_bids = []
    for opp in competitive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_competitive_bids.append(prev['bid'])

    if yesterday_competitive_bids:
        highest_prev_bid = max(yesterday_competitive_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, highest_prev_bid * 1.1)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)
    elif day_context['day'] <= 2:
        if my_status['hp'] > 5:
            base_bid = min(base_bid, DAILY_SALARY * 0.6)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(0.01, final_bid)

    if my_status['no_water_days'] > 0 and my_status['hp'] <= 1:
        final_bid = my_status['budget']

    return final_bid
